import{_ as e,o as a,c as d,al as r}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"SIH on Flight Controller Hardware","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sim_sih/hardware.md","filePath":"zh/sim_sih/hardware.md"}'),o={name:"zh/sim_sih/hardware.md"};function i(l,t,n,s,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="sih-on-flight-controller-hardware" tabindex="-1">SIH on Flight Controller Hardware <a class="header-anchor" href="#sih-on-flight-controller-hardware" aria-label="Permalink to &quot;SIH on Flight Controller Hardware&quot;">​</a></h1><p><a href="./../sim_sih/">SIH</a> can run directly on flight controller hardware with <code>SYS_AUTOSTART</code> set to the desired value for the frame. This replaces real sensors with simulated data while running on the actual autopilot.</p><p>For a comparison of SIH and HITL on hardware, see <a href="./../simulation/hardware">Hardware Simulation</a>.</p><h2 id="starting-sih" tabindex="-1">Starting SIH <a class="header-anchor" href="#starting-sih" aria-label="Permalink to &quot;Starting SIH&quot;">​</a></h2><ol><li>Connect the flight controller to QGroundControl via USB.</li><li>Set <code>SYS_AUTOSTART</code> parameter to the desired airframe.</li><li>Reboot the flight controller.</li><li>The SIH module starts automatically and provides simulated sensor data.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To ensure there is no leftover parameter from previous setup, it is recommended to reset all the parameters to firmware&#39;s default before modifying <code>SYS_AUTOSTART</code>.</p></div><p>The following airframes are supported.</p><table tabindex="0"><thead><tr><th>SIH Airframe</th><th>SYS_AUTOSTART</th><th>Status</th></tr></thead><tbody><tr><td>Quadrotor X</td><td>1100</td><td>Stable</td></tr><tr><td>Airplane</td><td>1101</td><td>Experimental</td></tr><tr><td>Tailsitter Duo</td><td>1102</td><td>Experimental</td></tr><tr><td>标准垂起固定翼</td><td>1103</td><td>Experimental</td></tr><tr><td>Ackermann Rover</td><td>1104</td><td>Experimental</td></tr><tr><td>Hexacopter X</td><td>1105</td><td>Experimental</td></tr></tbody></table><p>Once running, the vehicle can be controlled from QGroundControl or an RC controller.</p><h2 id="firmware-builds-with-sih" tabindex="-1">Firmware Builds with SIH <a class="header-anchor" href="#firmware-builds-with-sih" aria-label="Permalink to &quot;Firmware Builds with SIH&quot;">​</a></h2><p>The SIH module is included in many, but not all, default firmware builds. This list can change between PX4 releases. Always verify using the method in <a href="#check-if-sih-is-in-firmware">Check if SIH is in Firmware</a>.</p><p>The table below lists build targets that include SIH at the time of writing:</p><table tabindex="0"><thead><tr><th>Build Target</th><th>Board</th></tr></thead><tbody><tr><td><code>px4_fmu-v3_default</code></td><td>Pixhawk 2 (Cube Black)</td></tr><tr><td><code>px4_fmu-v4_default</code></td><td>Pixhawk 3 Pro</td></tr><tr><td><code>px4_fmu-v4pro_default</code></td><td>Pixracer</td></tr><tr><td><code>px4_fmu-v5_default</code></td><td>Pixhawk 4</td></tr><tr><td><code>px4_fmu-v5x_default</code></td><td>Pixhawk 5X</td></tr><tr><td><code>px4_fmu-v6c_default</code></td><td>Pixhawk 6C</td></tr><tr><td><code>px4_fmu-v6c_raptor</code></td><td>Pixhawk 6C (Raptor)</td></tr><tr><td><code>px4_fmu-v6x_multicopter</code></td><td>Pixhawk 6X (multicopter)</td></tr><tr><td><code>auterion_fmu-v6s_default</code></td><td>Auterion FMU-v6S</td></tr><tr><td><code>auterion_fmu-v6x_default</code></td><td>Auterion FMU-v6X</td></tr><tr><td><code>holybro_durandal-v1_default</code></td><td>Holybro Durandal</td></tr><tr><td><code>holybro_kakuteh7_default</code></td><td>Holybro Kakute H7</td></tr><tr><td><code>holybro_kakuteh7v2_default</code></td><td>Holybro Kakute H7 V2</td></tr><tr><td><code>holybro_pix32v5_default</code></td><td>Holybro Pix32 V5</td></tr><tr><td><code>cuav_nora_default</code></td><td>CUAV Nora</td></tr><tr><td><code>cuav_x7pro_default</code></td><td>CUAV X7 Pro</td></tr><tr><td><code>cuav_x25-evo_default</code></td><td>CUAV X25 EVO</td></tr><tr><td><code>cuav_x25-super_default</code></td><td>CUAV X25 Super</td></tr><tr><td><code>cubepilot_cubeyellow_default</code></td><td>CubePilot Cube Yellow</td></tr><tr><td><code>mro_pixracerpro_default</code></td><td>MRO PixRacer Pro</td></tr><tr><td><code>mro_x21_default</code></td><td>MRO X2.1</td></tr><tr><td><code>mro_ctrl-zero-h7_default</code></td><td>MRO Ctrl Zero H7</td></tr><tr><td><code>mro_ctrl-zero-h7-oem_default</code></td><td>MRO Ctrl Zero H7 OEM</td></tr><tr><td><code>mro_ctrl-zero-f7_default</code></td><td>MRO Ctrl Zero F7</td></tr><tr><td><code>mro_ctrl-zero-f7-oem_default</code></td><td>MRO Ctrl Zero F7 OEM</td></tr><tr><td><code>mro_ctrl-zero-classic_default</code></td><td>MRO Ctrl Zero Classic</td></tr><tr><td><code>3dr_ctrl-zero-h7-oem-revg_default</code></td><td>3DR Ctrl Zero H7 OEM RevG</td></tr><tr><td><code>modalai_fc-v1_default</code></td><td>ModalAI FC V1</td></tr><tr><td><code>nxp_fmuk66-v3_default</code></td><td>NXP FMUK66-V3</td></tr><tr><td><code>nxp_fmuk66-e_default</code></td><td>NXP FMUK66-E</td></tr><tr><td><code>radiolink_PIX6_default</code></td><td>Radiolink PIX6</td></tr><tr><td><code>siyi_n7_default</code></td><td>SIYI N7</td></tr><tr><td><code>sky-drones_smartap-airlink_default</code></td><td>Sky-Drones SmartAP Airlink</td></tr><tr><td><code>uvify_core_default</code></td><td>UVify Core</td></tr><tr><td><code>atl_mantis-edu_default</code></td><td>ATL Mantis EDU</td></tr><tr><td><code>av_x-v1_default</code></td><td>AV X-V1</td></tr><tr><td><code>narinfc_h7_default</code></td><td>NarinFC H7</td></tr><tr><td><code>thepeach_k1_default</code></td><td>ThePeach K1</td></tr><tr><td><code>thepeach_r1_default</code></td><td>ThePeach R1</td></tr><tr><td><code>airmind_mindpx-v2_default</code></td><td>AirMind MindPX V2</td></tr><tr><td><code>beaglebone_blue_default</code></td><td>BeagleBone Blue</td></tr><tr><td><code>bluerobotics_navigator_default</code></td><td>BlueRobotics Navigator</td></tr><tr><td><code>emlid_navio2_default</code></td><td>Emlid Navio2</td></tr><tr><td><code>px4_raspberrypi_default</code></td><td>通用依赖</td></tr><tr><td><code>scumaker_pilotpi_default</code></td><td>Scumaker PilotPi</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Some boards (e.g., <code>px4_fmu-v6x_default</code>, <code>cubepilot_cubeorange_default</code>) do not include SIH in their default build due to flash memory constraints. You can add SIH to any board -- see <a href="#check-if-sih-is-in-firmware">Check if SIH is in Firmware</a>.</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A flight controller with SIH module included in firmware (see <a href="#firmware-builds-with-sih">Firmware Builds with SIH</a>).</li><li>USB connection for QGroundControl.</li><li>Optional: jMAVSim for 3D visualization via serial link (see <a href="#hardware-visualization">Visualization</a>).</li></ul><h2 id="check-if-sih-is-in-firmware" tabindex="-1">Check if SIH is in Firmware <a class="header-anchor" href="#check-if-sih-is-in-firmware" aria-label="Permalink to &quot;Check if SIH is in Firmware&quot;">​</a></h2><p>SIH is included in <a href="#check-if-sih-is-in-firmware">most default firmware builds</a>. To verify, search for <code>sih</code> in the parameter list in QGroundControl. If <code>SIH_*</code> parameters are available, the module is included.</p><p>To add SIH to a custom build, enable it in the board configuration:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_MODULES_SIMULATION_SIMULATOR_SIH=y</span></span></code></pre></div><h2 id="hardware-visualization" tabindex="-1">Visualization (Optional) <a class="header-anchor" href="#hardware-visualization" aria-label="Permalink to &quot;Visualization (Optional) {#hardware-visualization}&quot;">​</a></h2><p>If you need a visual aid to see what the simulated vehicle is doing on hardware:</p><h3 id="qgroundcontrol" tabindex="-1">QGroundControl <a class="header-anchor" href="#qgroundcontrol" aria-label="Permalink to &quot;QGroundControl&quot;">​</a></h3><p>Connect the flight controller via USB. QGC shows the vehicle on the map view with attitude, position, and telemetry, the same as a real flight.</p><h3 id="jmavsim-3d-display-only" tabindex="-1">jMAVSim (3D Display-Only) <a class="header-anchor" href="#jmavsim-3d-display-only" aria-label="Permalink to &quot;jMAVSim (3D Display-Only)&quot;">​</a></h3><p>jMAVSim can render a 3D view of the vehicle over a serial connection. No physics are simulated in jMAVSim -- it is display-only.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/simulation/jmavsim/jmavsim_run.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2000000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div><p>Where <code>/dev/ttyACM0</code> is the serial device for the flight controller. On macOS, this is typically <code>/dev/tty.usbmodem*</code>.</p><h2 id="controlling-actuators" tabindex="-1">Controlling Actuators <a class="header-anchor" href="#controlling-actuators" aria-label="Permalink to &quot;Controlling Actuators&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you want to control throttle actuators in SIH, make sure to remove propellers for safety.</p></div><p>In some scenarios, it may be useful to control an actuator while running SIH on hardware. For example, you might want to verify that winches or grippers are functioning correctly by checking the servo responses.</p><p><strong>To enable actuator control in SIH:</strong></p><ol><li><p>Configure PWM parameters in the airframe file:</p><p>Ensure your airframe file includes the necessary parameters to map PWM outputs to the correct channels.</p><p>For example, if a servo is connected to MAIN 3 and you want to map it to AUX1 on your RC, use the following command:</p><p><code>param set-default PWM_MAIN_FUNC3 407</code></p><p>You can find a full list of available values for <code>PWM_MAIN_FUNCn</code> <a href="./../advanced_config/parameter_reference#PWM_MAIN_FUNC1">here</a>. In this case, <code>407</code> maps the MAIN 3 output to AUX1 on the RC.</p><p>Alternatively, you can use the <a href="./../advanced_config/parameter_reference#PWM_AUX_FUNC1"><code>PWM_AUX_FUNCn</code></a> parameters.</p><p>You may also configure the output as desired:</p><ul><li>Disarmed PWM: (<a href="./../advanced_config/parameter_reference#PWM_MAIN_DIS1"><code>PWM_MAIN_DISn</code></a> / <a href="./../advanced_config/parameter_reference#PWM_AUX_DIS1"><code>PWM_AUX_DIS1</code></a>)</li><li>Minimum PWM (<a href="./../advanced_config/parameter_reference#PWM_MAIN_MIN1"><code>PWM_MAIN_MINn</code></a> / <a href="./../advanced_config/parameter_reference#PWM_AUX_MIN1"><code>PWM_AUX_MINn</code></a>)</li><li>Maximum PWM (<a href="./../advanced_config/parameter_reference#PWM_MAIN_MAX1"><code>PWM_MAIN_MAXn</code></a> / <a href="./../advanced_config/parameter_reference#PWM_AUX_MAX1"><code>PWM_AUX_MAXn</code></a>)</li></ul></li><li><p>Manually start the PWM output driver</p><p>For safety, the PWM driver is not started automatically in SIH. To enable it, run the following command in the MAVLink shell:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pwm_out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><strong>And to disable it again:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pwm_out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div></li></ol><h2 id="adding-new-airframes-fc" tabindex="-1">Adding New Airframes (FC) <a class="header-anchor" href="#adding-new-airframes-fc" aria-label="Permalink to &quot;Adding New Airframes (FC)&quot;">​</a></h2><p>Airframe configuration for SIH on a flight controller differs from SITL in a few ways:</p><ul><li>Airframe file goes in <code>ROMFS/px4fmu_common/init.d/airframes</code> and follows the naming template <code>${ID}_${model_name}.hil</code>, where <code>ID</code> is the <code>SYS_AUTOSTART_ID</code> used to select the airframe, and <code>model_name</code> is the airframe model name.</li><li>Add the model name in <code>ROMFS/px4fmu_common/init.d/airframes/CMakeLists.txt</code> to generate a corresponding make target.</li><li>Actuators are configured with <code>HIL_ACT_FUNC*</code> parameters (not the usual <code>PWM_MAIN_FUNC*</code> parameters). This is to avoid using the real actuator outputs in SIH. Similarly, the bitfield for inverting individual actuator output ranges is <code>HIL_ACT_REV</code>, rather than <code>PWM_MAIN_REV</code>.</li></ul><p>For general airframe setup (SIH parameters, EKF2 tuning), see <a href="./#adding-new-airframes">Adding New Airframes</a> on the main SIH page.</p><p>For examples, see the <code>.hil</code> airframes in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/ROMFS/px4fmu_common/init.d/airframes" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d/airframes</a>.</p>',38)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
